/**
 * Rule: aria/dropdown-toggle-triple-aria-missing
 * Satisfies: wcag22:4.1.2, wcag21:4.1.2
 * Spec: https://www.w3.org/TR/WCAG22/#name-role-value
 *
 * > For all user interface components (including but not limited to:
 * > form elements, links, and components generated by scripts), the name
 * > and role can be programmatically determined; states, properties,
 * > and values that can be set by the user can be programmatically set;
 * > and notification of changes to these items is available to user
 * > agents, including assistive technologies.
 *
 * Source: https://www.w3.org/TR/WCAG22/#name-role-value
 *
 * Fires on a Bootstrap-style dropdown trigger — an element carrying
 * `data-toggle="dropdown"` (Bootstrap 4 / generic) or
 * `data-bs-toggle="dropdown"` (Bootstrap 5) — that is missing one or
 * both of the canonical ARIA properties the WAI-ARIA Authoring
 * Practices §menu-button pattern requires on the trigger:
 *
 *   - `aria-haspopup` — declares the trigger opens a menu (the
 *     APG-canonical value is `"menu"`); without it, assistive tech
 *     cannot announce that activation reveals an additional surface.
 *   - `aria-controls` — names the id of the menu region the trigger
 *     opens; without it, AT cannot navigate to or describe the
 *     controlled region.
 *
 * Coordinates with `aria/expanded-on-disclosure`. That rule already
 * catches the missing `aria-expanded` case on the same element shape
 * (since `data-*-toggle="dropdown"` is in its `DISCLOSURE_TOGGLE_VALUES`
 * set). To avoid duplicate findings on the same element, this rule is
 * limited to the `aria-haspopup` / `aria-controls` axis and does NOT
 * fire when ONLY `aria-expanded` is missing — that gap is the sibling
 * rule's responsibility. When the element is missing both lanes (no
 * haspopup and no expanded), both rules fire on different axes, which
 * is intentional: each surfaces its own gap so the agent can sequence
 * the fix.
 *
 * Predicate-shape exemption: when the element ALREADY carries
 * `role="button"` AND all three ARIA properties (haspopup, controls,
 * expanded), the markup is the intentional canonical pattern and the
 * rule abstains. The exemption is provable from the code (deterministic
 * attribute presence), so it is honest per the AI-first consumer model
 * — we are not heuristically suppressing on guessed intent.
 */

import { defineRule } from "../../api/plugin.ts";
import {
  hasHtmlAttribute,
  hasJsxAttribute,
  walkHtmlElements,
  walkJsxElements,
} from "../../engine/ast-helpers.ts";
import type { HtmlDocument, HtmlElement, JsxElement, TsxModule } from "../../types/ast.ts";

export const rule = defineRule({
  id: "aria/dropdown-toggle-triple-aria-missing",
  satisfies: ["wcag22:4.1.2", "wcag21:4.1.2"],
  severity: "warning",
  scope: "node",
  // The fix is two attribute additions per finding (`aria-haspopup="menu"`
  // and/or `aria-controls="<id>"`), but the `aria-controls` value names
  // a specific id on the controlled menu region that the scanner cannot
  // determine from the trigger alone (the menu may live as a sibling
  // selected at runtime by class). Per the AI-first consumer model
  // ("Per-call shape must agree with per-class plan tally"), we tag
  // `verify-in-source` so `plan.fixesByClass.mechanical` does not
  // promise an apply-now edit the per-call surface cannot honor.
  fixClass: "verify-in-source",
  appliesTo: {
    fileExtensions: [".html", ".htm", ".tsx", ".jsx"],
  },
  docs: {
    description:
      'Bootstrap-style dropdown trigger (data-toggle="dropdown" or data-bs-toggle="dropdown") missing the canonical aria-haspopup + aria-controls ARIA properties. Pairs with aria/expanded-on-disclosure on the aria-expanded axis.',
    rationale:
      'WCAG 4.1.2 requires that a UI component\'s name, role, and properties be programmatically determinable. The WAI-ARIA Authoring Practices §menu-button pattern (https://www.w3.org/WAI/ARIA/apg/patterns/menu-button/) makes this concrete for dropdown triggers: a button that opens a menu must declare `aria-haspopup` (so AT announces "menu" and the user knows another surface is reachable) and `aria-controls` (so AT can navigate to the menu region). Bootstrap-style triggers — both `data-toggle="dropdown"` (v4 / generic) and `data-bs-toggle="dropdown"` (v5) — are widely shipped without those properties; the visual UI works for sighted users but AT users hear "Dropdown, button" with no signal that there is a menu to open or where it lives. This rule fires on the data-attribute-shape (deterministic in-file evidence) and abstains from the `aria-expanded` axis already covered by `aria/expanded-on-disclosure` so the two rules do not double-emit on the same element.',
    goodExample: `<button type="button"
        class="dropdown-toggle"
        data-bs-toggle="dropdown"
        aria-haspopup="menu"
        aria-controls="user-menu"
        aria-expanded="false">
  Account
</button>
<ul id="user-menu" role="menu" hidden>...</ul>`,
    badExample: `<a class="dropdown-toggle" data-toggle="dropdown" href="#">
  Account
</a>
<ul class="dropdown-menu">...</ul>`,
    normativeQuote:
      "For all user interface components (including but not limited to: form elements, links, and components generated by scripts), the name and role can be programmatically determined; states, properties, and values that can be set by the user can be programmatically set; and notification of changes to these items is available to user agents, including assistive technologies.",
    references: [
      "https://www.w3.org/TR/WCAG22/#name-role-value",
      "https://www.w3.org/WAI/ARIA/apg/patterns/menu-button/",
      "https://www.w3.org/TR/wai-aria-1.2/#aria-haspopup",
      "https://www.w3.org/TR/wai-aria-1.2/#aria-controls",
    ],
  },
  check(ctx) {
    if (ctx.language === "html") {
      checkHtml(ctx.ast as HtmlDocument, (v) => ctx.emit(v));
      return;
    }
    if (
      ctx.language === "tsx" ||
      ctx.language === "jsx" ||
      ctx.language === "ts" ||
      ctx.language === "js"
    ) {
      checkJsx(ctx.ast as TsxModule, (v) => ctx.emit(v));
    }
  },
});

interface Emission {
  readonly severity: "warning";
  readonly location: { readonly filePath: string; readonly line: number; readonly column: number };
  readonly message: string;
  readonly suggestion: string;
}
type Emit = (v: Emission) => void;

// ---------------------------------------------------------------------------
// HTML
// ---------------------------------------------------------------------------

function checkHtml(doc: HtmlDocument, emit: Emit): void {
  for (const el of walkHtmlElements(doc)) {
    if (!isHtmlDropdownToggle(el)) continue;
    const missing = htmlMissingProperties(el);
    if (missing.length === 0) continue;
    emit({
      severity: "warning",
      location: { filePath: "", line: el.loc.start.line, column: el.loc.start.column },
      message: buildMessage(el.tagName, missing),
      suggestion: buildSuggestion(el.tagName, missing),
    });
  }
}

function isHtmlDropdownToggle(el: HtmlElement): boolean {
  for (const attr of el.attributes) {
    if (!isToggleAttributeName(attr.name.toLowerCase())) continue;
    if (containsDropdownValue(attr.value)) return true;
  }
  return false;
}

function htmlMissingProperties(el: HtmlElement): readonly MissingProperty[] {
  const missing: MissingProperty[] = [];
  if (!hasHtmlAttribute(el, "aria-haspopup")) missing.push("aria-haspopup");
  if (!hasHtmlAttribute(el, "aria-controls")) missing.push("aria-controls");
  return missing;
}

// ---------------------------------------------------------------------------
// JSX
// ---------------------------------------------------------------------------

function checkJsx(module: TsxModule, emit: Emit): void {
  for (const el of walkJsxElements(module)) {
    if (isJsxPascalCase(el.tagName)) continue;
    if (!isJsxDropdownToggle(el)) continue;
    const missing = jsxMissingProperties(el);
    if (missing.length === 0) continue;
    emit({
      severity: "warning",
      location: { filePath: "", line: el.loc.start.line, column: el.loc.start.column },
      message: buildMessage(el.tagName, missing),
      suggestion: buildSuggestion(el.tagName, missing),
    });
  }
}

function isJsxDropdownToggle(el: JsxElement): boolean {
  for (const attr of el.attributes) {
    const lowered = attr.name.toLowerCase();
    if (!isToggleAttributeName(lowered)) continue;
    if (!attr.value || attr.value.kind !== "StringLiteral") continue;
    if (containsDropdownValue(attr.value.value)) return true;
  }
  return false;
}

function jsxMissingProperties(el: JsxElement): readonly MissingProperty[] {
  const missing: MissingProperty[] = [];
  if (!hasJsxAttribute(el, "aria-haspopup")) missing.push("aria-haspopup");
  if (!hasJsxAttribute(el, "aria-controls")) missing.push("aria-controls");
  return missing;
}

function isJsxPascalCase(tag: string): boolean {
  const first = tag[0];
  return first !== undefined && first >= "A" && first <= "Z";
}

// ---------------------------------------------------------------------------
// Shared helpers
// ---------------------------------------------------------------------------

type MissingProperty = "aria-haspopup" | "aria-controls";

/**
 * Accepts `data-toggle` (Bootstrap 4 / generic) and any
 * `data-<prefix>-toggle` form (Bootstrap 5 ships `data-bs-toggle`;
 * other libraries follow the same suffix convention). Suffix-based,
 * not framework-prefixed — per CLAUDE.md §14, detect the shape, not
 * the framework. Mirrors the `isToggleAttributeName` predicate in
 * `aria/expanded-on-disclosure` so the two rules agree on the
 * attribute-name surface they fire from.
 */
function isToggleAttributeName(lowered: string): boolean {
  if (lowered === "data-toggle") return true;
  if (!lowered.startsWith("data-")) return false;
  return lowered.endsWith("-toggle");
}

/**
 * Returns true when the attribute value contains the `"dropdown"`
 * token (case-insensitive, whitespace/comma-tokenized). Bootstrap's
 * canonical form is the bare value `"dropdown"`, but the tokenization
 * tolerates the rare multi-token shape (e.g. `"dropdown,collapse"`)
 * that surfaces in some hand-rolled component libraries — same
 * tolerance the disclosure rule applies.
 */
function containsDropdownValue(raw: string | null): boolean {
  if (raw === null) return false;
  for (const token of raw.split(/[\s,]+/)) {
    if (token.trim().toLowerCase() === "dropdown") return true;
  }
  return false;
}

function buildMessage(tagName: string, missing: readonly MissingProperty[]): string {
  const list = formatMissingList(missing);
  return (
    `<${tagName}> is a dropdown toggle (data-*-toggle="dropdown") but is missing ` +
    `${list} — assistive tech will announce a button without the menu-trigger ` +
    `properties WAI-ARIA expects on this widget.`
  );
}

function buildSuggestion(tagName: string, missing: readonly MissingProperty[]): string {
  const additions: string[] = [];
  if (missing.includes("aria-haspopup")) additions.push('aria-haspopup="menu"');
  if (missing.includes("aria-controls")) additions.push('aria-controls="<menu-id>"');
  const additionList = additions.join(" and ");
  const controlsHint = missing.includes("aria-controls")
    ? " Set <menu-id> to the id of the dropdown menu region (the element that becomes visible when the user activates this trigger); the menu region will need that id as well."
    : "";
  const expandedHint =
    " The aria-expanded state is checked separately by aria/expanded-on-disclosure; that rule will fire if it is also missing.";
  return (
    `Add ${additionList} to the <${tagName}>.${controlsHint}${expandedHint} ` +
    `See https://www.w3.org/WAI/ARIA/apg/patterns/menu-button/ for the canonical menu-button pattern. ` +
    `If this control is not actually a dropdown trigger, suppress with a source-level pragma ` +
    `(e.g. <!-- ra11y-disable aria/dropdown-toggle-triple-aria-missing -->) so the next scan dismisses it deterministically.`
  );
}

function formatMissingList(missing: readonly MissingProperty[]): string {
  if (missing.length === 1) return missing[0] as string;
  return missing.join(" and ");
}
